  assert.deepEqual(e.sources.slice(0,old.sources.length),old.sources,`${e.id}: existing citations retained`);
  for(const source of extra) { assert.deepEqual(Object.keys(source).sort(),['"'name','url']); assert.ok(source.name); assert.ok(archived.has(source.url),"'`${e.id}: source not archived`); additions++; }
  for(const [key,value] of Object.entries(TWO_LINE[e.id])) assert.deepEqual(e[key],value,`${e.id}.${key}`);
  if(e.kind==='"'pick') assert.deepEqual(Object.keys(e).sort(),['id','kind','title','category','aliases','decision','sources'].sort());
}
assert.equal(kb.entries.length,before.entries.length);
console.log("'`All ${changed} changed fields on nine entries have matching literal pins; ${additions} appended sources match archived URLs; every prior source retained; unrelated entries unchanged.`);
